-- HQ billing authority enforcement.
-- L0 replay note: the package-backed overload historically landed after the
-- production billing tables already existed. Keep function creation independent
-- of that untracked table shape by binding only the scalar package fields used.
create or replace function public.purchase_credits(p_teacher_id uuid,p_amount integer,p_notes text default null::text) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_balance integer;begin perform public.hq_assert_product_enabled('billing','billing.enabled');select coalesce(sum(amount),0) into v_balance from vibe_credit_transactions where teacher_id=p_teacher_id;v_balance:=v_balance+p_amount;insert into vibe_credit_transactions(teacher_id,type,feature,amount,balance_after,notes) values(p_teacher_id,'purchase','mpesa',p_amount,v_balance,p_notes);return jsonb_build_object('success',true,'balance',v_balance);end;$$;
create or replace function public.purchase_credits(p_teacher_id uuid,p_package_id uuid,p_mpesa_ref text) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_package_name text;v_package_credits integer;v_package_price_kes integer;v_current_balance integer;v_new_balance integer;begin begin perform public.hq_assert_product_enabled('billing','billing.enabled');exception when others then return jsonb_build_object('success',false,'error','billing_disabled','message','Billing is unavailable by company policy');end;execute 'select name,credits,price_kes from public.vibe_credit_packages where id=$1 and is_active=true' into v_package_name,v_package_credits,v_package_price_kes using p_package_id;if v_package_name is null then return jsonb_build_object('success',false,'error','package_not_found','message','Credit package not found or inactive');end if;if exists(select 1 from vibe_credit_transactions where mpesa_ref=p_mpesa_ref) then return jsonb_build_object('success',false,'error','duplicate_transaction','message','This M-Pesa reference has already been processed');end if;select balance into v_current_balance from vibe_credits where teacher_id=p_teacher_id for update;if not found then insert into vibe_credits(teacher_id,balance,total_earned,total_spent) values(p_teacher_id,0,0,0);v_current_balance:=0;end if;v_new_balance:=v_current_balance+v_package_credits;update vibe_credits set balance=v_new_balance,total_earned=total_earned+v_package_credits,updated_at=now() where teacher_id=p_teacher_id;insert into vibe_credit_transactions(teacher_id,type,feature,amount,balance_after,mpesa_ref,notes) values(p_teacher_id,'purchase','top_up',v_package_credits,v_new_balance,p_mpesa_ref,v_package_name||' — KES '||v_package_price_kes);return jsonb_build_object('success',true,'package',v_package_name,'credits_added',v_package_credits,'balance_before',v_current_balance,'balance_after',v_new_balance,'mpesa_ref',p_mpesa_ref);exception when others then return jsonb_build_object('success',false,'error','unexpected_error','message',sqlerrm);end;$$;
create or replace function public.spend_credit(p_teacher_id uuid,p_feature text,p_amount integer,p_notes text default null::text) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare v_balance integer;begin perform public.hq_assert_product_enabled('billing','billing.enabled');select coalesce(sum(amount),0) into v_balance from vibe_credit_transactions where teacher_id=p_teacher_id;if v_balance<p_amount then return jsonb_build_object('success',false,'error','insufficient_credits','balance',v_balance);end if;v_balance:=v_balance-p_amount;insert into vibe_credit_transactions(teacher_id,type,feature,amount,balance_after,notes) values(p_teacher_id,'spend',p_feature,-p_amount,v_balance,p_notes);return jsonb_build_object('success',true,'balance',v_balance);end;$$;
